function validatePaymentDetails(payment: PaymentDetails): boolean {
  const { cardNumber, expiryDate, cvv } = payment;

  const isCardNumberValid = cardNumber.length === 16;
  const isCvvValid = cvv.length === 3 || cvv.length === 4;
  const isExpiryFormatValid = /^(0[1-9]|1[0-2])\/\d{2}$/.test(expiryDate);

  if (!isCardNumberValid || !isCvvValid || !isExpiryFormatValid) {
    return false;
  }

  const [month, year] = expiryDate.split('/');
  const expiryDateObj = new Date(2000 + parseInt(year), parseInt(month) - 1);
  const isNotExpired = expiryDateObj >= new Date();

  return isNotExpired;
}

